const downtime_cost_per_hour = 10_000;
const rto_options = [
  {name: "Active-active", rto: 0.25, rpo: 0, cost_per_month: 50_000},
  {name: "Active-passive", rto: 4, rpo: 0.25, cost_per_month: 10_000},
  {name: "Warm standby", rto: 24, rpo: 1, cost_per_month: 2_000},
];
rto_options.forEach(opt => {
  const annual_downtime_cost = downtime_cost_per_hour * opt.rto * 12;
  const annual_dr_cost = opt.cost_per_month * 12;
  const roi = (annual_downtime_cost - annual_dr_cost) / annual_dr_cost;
  console.log(opt.name + ": ROI=" + roi.toFixed(1) + "x");
});

const DR_SUMMARY = {
  rto_target: "4 hours",
  rto_actual: "2.5 hours",
  rpo_target: "15 minutes",
  rpo_actual: "10 minutes",
  cost_per_month: "$5,000",
  business_impact: "Can recover from any single-region failure within RTO",
  recommendation: "Increase DR investment to support multi-region active-active"
};
